function Shell({ page, setPage, children, openCommand }:{ page:Page; setPage:(p:Page)=>void; children:React.ReactNode; openCommand:()=>void }) {
  return <main className="app-shell">
    <header className="topbar">
      <button className="brand" onClick={()=>setPage('Overview')}><img src="/scout-logo.png" alt="" /><span>SCOUT</span></button>
      <div className="workspace-name">Sales workspace <FiChevronDown /></div>
      <div className="top-actions"><button className="search" onClick={openCommand}><FiSearch /> Search <kbd>⌘ K</kbd></button><button className="icon-button" aria-label="Notifications"><FiBell /></button><div className="avatar">SD</div></div>
    </header>
    <div className="subbar"><div className="sub-context"><span>Sales</span><strong>{page}</strong></div><div className="sub-actions"><button onClick={openCommand}><FiSearch /> Search this view</button><button aria-label="More page actions"><FiMoreHorizontal /></button></div></div>
    {children}
  </main>
}

function UtilityRail({ page, setPage }:{page:Page;setPage:(p:Page)=>void}) {
  const items = [{name:'Overview' as Page,icon:FiHome},{name:'Leads' as Page,icon:FiUsers},{name:'Finder' as Page,icon:FiTarget},{name:'Pipeline' as Page,icon:FiColumns},{name:'Tasks' as Page,icon:FiCheckSquare},{name:'Activities' as Page,icon:FiActivity}];
  return <aside className="utility-rail"><div>{items.map(({name,icon:Icon})=><button className={page===name?'active':''} onClick={()=>setPage(name)} aria-label={name} title={name} key={name}><Icon /></button>)}</div><button aria-label="Settings" title="Settings"><FiSettings /></button></aside>
}

function ContextSidebar({page,setPage,leadView,setLeadView,finderView,setFinderView}:{page:Page;setPage:(p:Page)=>void;leadView:string;setLeadView:(v:string)=>void;finderView:string;setFinderView:(v:string)=>void}) {
  const context:Record<Page,string[]>={Overview:['My day','Team pulse','Campaigns'],Leads:['All leads','Assigned to me','Recently added','High priority'],Finder:['New search','Campaigns','Saved searches'],Pipeline:['All pipeline','My pipeline','Forecast'],Tasks:['Today','Upcoming','Completed'],Activities:['All activity','Calls','Notes','Proposals']};
  return <aside className="context-sidebar"><h2>{page}</h2><nav>{context[page].map((item,i)=><button className={page==='Leads'?(leadView===item?'active':''):page==='Finder'?(finderView===item?'active':''):(i===0?'active':'')} onClick={()=>{if(page==='Leads')setLeadView(item);if(page==='Finder')setFinderView(item)}} key={item}>{item}{item==='My day'&&<span>16</span>}{item==='Campaigns'&&<span>4</span>}</button>)}</nav><div className="sidebar-actions"><button onClick={()=>setPage('Leads')}><FiPlus /> Create lead</button><button onClick={()=>{setPage('Finder');setFinderView('New search')}}><FiSearch /> Find businesses</button></div></aside>
}

function Heading({ title, action }:{title:string;action?:React.ReactNode}) {
  return <div className="page-head"><h1>{title}</h1>{action}</div>
}

function CustomSelect({value,options,onChange,placeholder,label}:{value:string;options:string[];onChange:(value:string)=>void;placeholder?:string;label?:string}) {
  const [open,setOpen]=useState(false); const [active,setActive]=useState(Math.max(0,options.indexOf(value)));
  const choose=(option:string)=>{onChange(option);setOpen(false)};
  const keys=(e:React.KeyboardEvent)=>{if(e.key==='Escape')setOpen(false);if(e.key==='ArrowDown'){e.preventDefault();setOpen(true);setActive(i=>Math.min(options.length-1,i+1))}if(e.key==='ArrowUp'){e.preventDefault();setOpen(true);setActive(i=>Math.max(0,i-1))}if(e.key==='Enter'&&open){e.preventDefault();choose(options[active])}};
  return <div className="custom-select" onKeyDown={keys} onBlur={e=>!e.currentTarget.contains(e.relatedTarget)&&setOpen(false)}>{label&&<span className="select-label">{label}</span>}<button type="button" className="select-trigger" aria-haspopup="listbox" aria-expanded={open} onClick={()=>setOpen(v=>!v)}><span>{value||placeholder||'Select'}</span><FiChevronDown/></button>{open&&<div className="select-menu" role="listbox">{options.map((option,i)=><button type="button" role="option" aria-selected={option===value} className={i===active?'active':''} onMouseEnter={()=>setActive(i)} onClick={()=>choose(option)} key={option}><span>{option}</span>{option===value&&<FiCheck/>}</button>)}</div>}</div>
}

function StatusSelect({value,onChange}:{value:string;onChange:(value:string)=>void}) {
  const [open,setOpen]=useState(false); const options=['New','Contacted','Interested','Follow-up','Proposal','Negotiation','Won','Lost']; const statusClass=(name:string)=>name.toLowerCase().replace('-','');
  return <div className="row-status-select" onClick={e=>e.stopPropagation()} onBlur={e=>!e.currentTarget.contains(e.relatedTarget)&&setOpen(false)}><button type="button" className="row-status-trigger" aria-haspopup="listbox" aria-expanded={open} onClick={()=>setOpen(v=>!v)}><i className={`status-dot ${statusClass(value)}`}/><span>{value}</span><FiChevronDown/></button>{open&&<div className="select-menu status-menu" role="listbox">{options.map(option=><button type="button" role="option" aria-selected={option===value} onClick={()=>{onChange(option);setOpen(false)}} key={option}><span><i className={`status-dot ${statusClass(option)}`}/>{option}</span>{option===value&&<FiCheck/>}</button>)}</div>}</div>
}

function Overview({setPage,leads}:{setPage:(p:Page)=>void;leads:Lead[]}) {
  const [done,setDone]=useState<string[]>([]);
  const tasks = leads.filter(l=>!['Won','Lost'].includes(l.status)).slice(0,4).map(l=>[l.next.split(' · ')[1]||'—',l.name,l.next.split(' · ')[0],l.priority]);
  const movements = [{label:'New leads',className:'blue',left:'4%',width:'28%'},{label:'Contacted',className:'rose',left:'17%',width:'31%'},{label:'Interested',className:'amber',left:'34%',width:'25%'},{label:'Proposal sent',className:'violet',left:'51%',width:'28%'},{label:'Won',className:'green',left:'69%',width:'22%'}];
  return <><Heading title="Sales overview" action={<button className="primary" onClick={()=>setPage('Leads')}><FiPlus /> Add lead</button>}/>
    <section className="overview-analysis"><div className="analysis-main"><div className="analysis-head"><div><button className="active">Pipeline movement</button><button>Activity volume</button></div><div><button>30 days</button><button aria-label="More options"><FiMoreHorizontal /></button></div></div><div className="movement-chart"><div className="chart-scale"><span>Jul 28</span><span>Aug 4</span><span>Aug 11</span><span>Aug 18</span><span>Aug 25</span></div><div className="chart-plot">{movements.map(m=><div className="movement-row" key={m.label}><span className="row-label">{m.label}</span><i className={m.className} style={{left:m.left,width:m.width}}>{m.label}</i></div>)}</div><div className="chart-legend"><span className="blue">New</span><span className="rose">Contacted</span><span className="amber">Interested</span><span className="violet">Proposal</span><span className="green">Won</span></div></div></div>
      <aside className="period-summary"><div><span>Active pipeline</span><strong>{leads.filter(l=>!['Won','Lost'].includes(l.status)).length} leads</strong></div><div><span>High priority</span><strong>{leads.filter(l=>l.priority==='High').length}</strong></div><div><span>Proposals</span><strong>{leads.filter(l=>l.status==='Proposal').length}</strong></div><div><span>Won this month</span><strong>{leads.filter(l=>l.status==='Won').length}</strong></div></aside>
    </section>
    <section className="today-work"><div className="section-head"><h2>Today&apos;s follow-ups</h2><button onClick={()=>setPage('Tasks')}>View all 16 →</button></div><div className="followup-table"><div className="followup-head"><span>Time</span><span>Business</span><span>Next action</span><span>Priority</span><span/></div>{tasks.map(t=><div className={done.includes(t[0])?'done':''} key={t[0]}><time>{t[0]}</time><strong>{t[1]}</strong><span>{t[2]}</span><em>{t[3]}</em><button onClick={()=>setDone(v=>v.includes(t[0])?v.filter(x=>x!==t[0]):[...v,t[0]])}>{done.includes(t[0])?<FiCheckSquare/>:<FiMoreHorizontal/>}</button></div>)}</div></section>
  </>;
}

function Leads({leads,setLeads,activities,setActivities,leadView,notify}:{leads:Lead[];setLeads:React.Dispatch<React.SetStateAction<Lead[]>>;activities:ActivityEntry[];setActivities:React.Dispatch<React.SetStateAction<ActivityEntry[]>>;leadView:string;notify:(s:string)=>void}) {
  const emptyForm={name:'',industry:'',city:'',owner:'Shaun',phone:'',email:'',contact:'',priority:'Medium'};
  const [query,setQuery]=useState(''); const [status,setStatus]=useState('All statuses'); const [owner,setOwner]=useState('All owners'); const [priority,setPriority]=useState('All priorities'); const [industry,setIndustry]=useState('All industries'); const [minimumScore,setMinimumScore]=useState('Any score'); const [showMoreFilters,setShowMoreFilters]=useState(false); const [sort,setSort]=useState<{key:'name'|'status'|'score'|'owner'|'next';direction:'asc'|'desc'}>({key:'name',direction:'asc'}); const [selectedName,setSelectedName]=useState<string|null>(null); const [creating,setCreating]=useState(false); const [checked,setChecked]=useState<string[]>([]); const [form,setForm]=useState(emptyForm); const [formError,setFormError]=useState(''); const [actionModal,setActionModal]=useState<string|null>(null); const [pendingStatus,setPendingStatus]=useState<string|null>(null); const [statusTarget,setStatusTarget]=useState<string|null>(null); const [statusReason,setStatusReason]=useState(''); const [modalForm,setModalForm]=useState({outcome:'Connected',notes:'',duration:'',package:'Growth',value:'',date:'',time:'',method:'Call'});
  const industries=useMemo(()=>['All industries',...Array.from(new Set(leads.map(l=>l.industry))).sort()],[leads]);
  const visible=useMemo(()=>{const scoreFloor=minimumScore==='Any score'?0:Number(minimumScore.replace('+',''));const filtered=leads.filter(l=>{const matches=(l.name+l.city+l.industry).toLowerCase().includes(query.toLowerCase())&&(status==='All statuses'||l.status===status)&&(owner==='All owners'||l.owner===owner)&&(priority==='All priorities'||l.priority===priority)&&(industry==='All industries'||l.industry===industry)&&l.score>=scoreFloor;if(!matches)return false;if(leadView==='Assigned to me')return l.owner==='Shaun';if(leadView==='Recently added')return l.last.includes('Today')||l.last==='Yesterday';if(leadView==='High priority')return l.priority==='High';return true});return [...filtered].sort((a,b)=>{const av=sort.key==='name'?a.name:sort.key==='next'?a.next:a[sort.key];const bv=sort.key==='name'?b.name:sort.key==='next'?b.next:b[sort.key];const result=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv));return sort.direction==='asc'?result:-result})},[leads,query,status,owner,priority,industry,minimumScore,leadView,sort]);
  const selected=leads.find(l=>l.name===selectedName)||null; const initials:Record<string,string>={Shaun:'SD',Mika:'MK',Paolo:'PL'};
  const updateLead=(name:string,patch:Partial<Lead>)=>setLeads(v=>v.map(l=>l.name===name?{...l,...patch}:l));
  const log=(lead:string,type:string,detail:string,ownerName:string)=>setActivities(v=>[{id:Date.now(),lead,type,detail,time:'Just now',owner:ownerName},...v]);
  const createLead=()=>{if(!form.name.trim()){setFormError('Business name is required.');return}const duplicate=leads.some(l=>(l.name.toLowerCase()===form.name.trim().toLowerCase()&&l.city.toLowerCase()===form.city.trim().toLowerCase())||(form.phone&&l.phone===form.phone));if(duplicate){setFormError('A matching lead already exists.');return}const lead:Lead={...form,name:form.name.trim(),status:'New',score:70,last:'Just now',next:'Initial call · Not scheduled',opportunity:'Research needed'};setLeads(v=>[lead,...v]);log(lead.name,'Lead added','Created manually',lead.owner);setForm(emptyForm);setFormError('');setCreating(false);notify(`${lead.name} created`)};
  const applyBulk=(patch:Partial<Lead>,label:string)=>{setLeads(v=>v.map(l=>checked.includes(l.name)?{...l,...patch}:l));checked.forEach(name=>log(name,label,label==='Assignment'?'Owner updated':'Status updated','Shaun'));notify(`${checked.length} leads updated`);setChecked([])};
  const submitAction=()=>{if(!selected||!actionModal)return;let detail=modalForm.notes.trim();if(actionModal==='Log call')detail=`${modalForm.outcome}${modalForm.duration?` · ${modalForm.duration} min`:''}${detail?` · ${detail}`:''}`;if(actionModal==='Proposal'){detail=`${modalForm.package} package${modalForm.value?` · ₱${modalForm.value}`:''}${detail?` · ${detail}`:''}`;updateLead(selected.name,{status:'Proposal'})}if(actionModal==='Follow-up'){detail=`${modalForm.method} · ${modalForm.date||'Date TBD'} ${modalForm.time}`;updateLead(selected.name,{next:`${modalForm.method} follow-up · ${modalForm.date||'Not scheduled'} ${modalForm.time}`})}log(selected.name,actionModal==='Add note'?'Note':actionModal.replace('Log ',''),detail||actionModal,selected.owner);updateLead(selected.name,{last:'Just now'});notify(`${actionModal} saved`);setActionModal(null);setModalForm({outcome:'Connected',notes:'',duration:'',package:'Growth',value:'',date:'',time:'',method:'Call'})};
  const statusLead=leads.find(l=>l.name===(statusTarget||selectedName))||null;
  const requestStatus=(leadName:string,value:string)=>{const lead=leads.find(l=>l.name===leadName);if(!lead||value===lead.status)return;setStatusTarget(leadName);setPendingStatus(value)};
  const confirmStatus=()=>{if(!statusLead||!pendingStatus)return;const detail=`${statusLead.status} → ${pendingStatus}${statusReason?` · ${statusReason}`:''}`;updateLead(statusLead.name,{status:pendingStatus});log(statusLead.name,'Status change',detail,statusLead.owner);notify(`Status changed to ${pendingStatus}`);setPendingStatus(null);setStatusTarget(null);setStatusReason('')};
  const changeSort=(key:'name'|'status'|'score'|'owner'|'next')=>setSort(current=>current.key===key?{key,direction:current.direction==='asc'?'desc':'asc'}:{key,direction:'asc'});
  return <><Heading title="Leads" action={<button className="primary" onClick={()=>setCreating(true)}><FiPlus/> Create lead</button>}/>
    <div className="lead-summary"><strong>{leads.filter(l=>!['Won','Lost'].includes(l.status)).length} active leads</strong><span>{leads.filter(l=>l.priority==='High').length} need attention</span><span>{leads.filter(l=>l.status==='Proposal').length} proposals</span></div>
    <div className="filters-wrap"><div className="filters"><div className="lead-search"><FiSearch/><input aria-label="Search leads" placeholder="Search leads…" value={query} onChange={e=>setQuery(e.target.value)}/></div><div className="filter-group"><CustomSelect value={status} options={['All statuses','New','Contacted','Interested','Follow-up','Proposal','Negotiation','Won','Lost']} onChange={setStatus}/><CustomSelect value={owner} options={['All owners','Shaun','Mika','Paolo']} onChange={setOwner}/><button className={showMoreFilters?'active':''} onClick={()=>setShowMoreFilters(v=>!v)}>More filters<FiChevronDown/></button></div><span>{visible.length} leads</span></div>{showMoreFilters&&<div className="more-filters"><CustomSelect label="Priority" value={priority} options={['All priorities','Low','Medium','High']} onChange={setPriority}/><CustomSelect label="Industry" value={industry} options={industries} onChange={setIndustry}/><CustomSelect label="Minimum score" value={minimumScore} options={['Any score','70+','80+','90+']} onChange={setMinimumScore}/><button onClick={()=>{setPriority('All priorities');setIndustry('All industries');setMinimumScore('Any score')}}>Clear filters</button></div>}</div>
    {checked.length>0&&<div className="bulk-bar"><strong>{checked.length} selected</strong><CustomSelect value="" placeholder="Assign owner" options={['Shaun','Mika','Paolo']} onChange={value=>applyBulk({owner:value},'Assignment')}/><CustomSelect value="" placeholder="Change status" options={['New','Contacted','Interested','Follow-up','Proposal','Negotiation','Won','Lost']} onChange={value=>applyBulk({status:value},'Status change')}/><button onClick={()=>setChecked([])}>Clear</button></div>}
    <div className="lead-table table"><div className="table-head"><span><input type="checkbox" aria-label="Select all leads" checked={checked.length===visible.length&&visible.length>0} onChange={()=>setChecked(checked.length===visible.length?[]:visible.map(l=>l.name))}/></span>{([['name','Business'],['status','Status'],['score','Score'],['owner','Owner'],['next','Next action']] as const).map(([key,label])=><button className={sort.key===key?'sorted':''} onClick={()=>changeSort(key)} key={key}>{label}<FiChevronDown className={sort.key===key&&sort.direction==='asc'?'ascending':''}/></button>)}<span/></div>{visible.map(l=>{const rank=l.score>=85?'High':l.score>=70?'Medium':'Low';return <div className="table-row" role="button" tabIndex={0} key={l.name} onClick={()=>setSelectedName(l.name)} onKeyDown={e=>e.key==='Enter'&&setSelectedName(l.name)}><span className="row-check"><input type="checkbox" aria-label={`Select ${l.name}`} checked={checked.includes(l.name)} onClick={e=>e.stopPropagation()} onChange={()=>setChecked(v=>v.includes(l.name)?v.filter(x=>x!==l.name):[...v,l.name])}/></span><span className="business-cell"><strong>{l.name}</strong><small>{l.industry} · {l.city}</small></span><span><StatusSelect value={l.status} onChange={value=>requestStatus(l.name,value)}/></span><span className="score"><strong>{l.score}</strong><small>{rank}</small></span><span className="owner"><i>{initials[l.owner]||l.owner.slice(0,2).toUpperCase()}</i>{l.owner}</span><span className="next-cell"><strong>{l.next.split(' · ')[0]}</strong><small>{l.next.split(' · ')[1]}</small></span><span className="row-chevron"><FiChevronRight/></span></div>})}</div>
    {(selected||creating)&&<div className="drawer-backdrop" onClick={()=>{setSelectedName(null);setCreating(false)}}><aside className="lead-drawer" onClick={e=>e.stopPropagation()}>{creating?<><header className="drawer-header"><div><h2>Create lead</h2><p>Add the business and assign its first owner.</p></div><button onClick={()=>setCreating(false)} aria-label="Close"><FiX/></button></header><div className="drawer-section create-fields"><label>Business name<input autoFocus value={form.name} onChange={e=>setForm({...form,name:e.target.value})}/></label><div className="form-split"><label>Industry<input value={form.industry} onChange={e=>setForm({...form,industry:e.target.value})}/></label><label>City<input value={form.city} onChange={e=>setForm({...form,city:e.target.value})}/></label></div><div className="form-split"><label>Contact name<input value={form.contact} onChange={e=>setForm({...form,contact:e.target.value})}/></label><label>Phone<input value={form.phone} onChange={e=>setForm({...form,phone:e.target.value})}/></label></div><label>Email<input type="email" value={form.email} onChange={e=>setForm({...form,email:e.target.value})}/></label><div className="form-split"><label>Owner<CustomSelect value={form.owner} options={['Shaun','Mika','Paolo']} onChange={value=>setForm({...form,owner:value})}/></label><label>Priority<CustomSelect value={form.priority} options={['Low','Medium','High']} onChange={value=>setForm({...form,priority:value})}/></label></div>{formError&&<p className="form-error">{formError}</p>}<div className="drawer-footer"><button onClick={()=>setCreating(false)}>Cancel</button><button className="primary" onClick={createLead}>Create lead</button></div></div></>:selected&&<><header className="drawer-header"><div><h2>{selected.name}</h2><p>{selected.industry} · {selected.city}</p></div><button onClick={()=>setSelectedName(null)} aria-label="Close"><FiX/></button></header><div className="detail-status"><div className="status-anchor"><span>Status</span><CustomSelect value={selected.status} options={['New','Contacted','Interested','Follow-up','Proposal','Negotiation','Won','Lost']} onChange={value=>requestStatus(selected.name,value)}/></div><div><span>Owner</span><CustomSelect value={selected.owner} options={['Shaun','Mika','Paolo']} onChange={value=>{updateLead(selected.name,{owner:value});log(selected.name,'Assignment',`Assigned to ${value}`,value)}}/></div><div><span>Score</span><strong>{selected.score}</strong></div></div><div className="quick-actions"><button onClick={()=>setActionModal('Log call')}><FiPhone/>Log call</button><button onClick={()=>setActionModal('Add note')}><FiEdit3/>Add note</button><button onClick={()=>setActionModal('Proposal')}><FiFileText/>Proposal</button><button onClick={()=>setActionModal('Follow-up')}><FiCalendar/>Follow-up</button></div><section className="drawer-section contact-section"><h3>Contact</h3><div><p><span>Contact</span>{selected.contact}</p><p><span>Phone</span>{selected.phone}</p><p><span>Email</span>{selected.email}</p><p><span>Opportunity</span>{selected.opportunity}</p></div></section><section className="drawer-section lead-activity"><h3>Activity</h3>{activities.filter(a=>a.lead===selected.name).map(a=><article key={a.id}><i/><div><strong>{a.type}</strong><p>{a.detail}</p><small>{a.time} · {a.owner}</small></div></article>)}</section><div className="close-actions"><button onClick={()=>requestStatus(selected.name,'Lost')}>Mark lost</button><button onClick={()=>requestStatus(selected.name,'Won')}>Mark won</button></div></>}</aside></div>}
    {actionModal&&selected&&<div className="action-modal-backdrop" onClick={()=>setActionModal(null)}><div className="action-modal" role="dialog" aria-modal="true" aria-labelledby="action-title" onClick={e=>e.stopPropagation()}><header><h2 id="action-title">{actionModal}</h2><button onClick={()=>setActionModal(null)} aria-label="Close"><FiX/></button></header><div className="action-modal-body">{actionModal==='Log call'&&<><label>Outcome<CustomSelect value={modalForm.outcome} options={['Connected','No answer','Voicemail','Not interested']} onChange={value=>setModalForm({...modalForm,outcome:value})}/></label><label>Duration (minutes)<input type="number" min="0" value={modalForm.duration} onChange={e=>setModalForm({...modalForm,duration:e.target.value})}/></label></>}{actionModal==='Proposal'&&<><label>Package<CustomSelect value={modalForm.package} options={['Starter','Growth','Premium','Custom']} onChange={value=>setModalForm({...modalForm,package:value})}/></label><label>Value<input type="number" min="0" placeholder="0" value={modalForm.value} onChange={e=>setModalForm({...modalForm,value:e.target.value})}/></label></>}{actionModal==='Follow-up'&&<><label>Method<CustomSelect value={modalForm.method} options={['Call','Email','Meeting']} onChange={value=>setModalForm({...modalForm,method:value})}/></label><div className="form-split"><label>Date<input type="date" value={modalForm.date} onChange={e=>setModalForm({...modalForm,date:e.target.value})}/></label><label>Time<input type="time" value={modalForm.time} onChange={e=>setModalForm({...modalForm,time:e.target.value})}/></label></div></>}<label>{actionModal==='Add note'?'Note':'Notes'}<textarea autoFocus={actionModal==='Add note'} placeholder="Add context…" value={modalForm.notes} onChange={e=>setModalForm({...modalForm,notes:e.target.value})}/></label></div><footer><button onClick={()=>setActionModal(null)}>Cancel</button><button className="primary" onClick={submitAction}>Save</button></footer></div></div>}
    {pendingStatus&&statusLead&&<div className="action-modal-backdrop" onClick={()=>{setPendingStatus(null);setStatusTarget(null)}}><div className="action-modal status-confirm" role="alertdialog" aria-modal="true" aria-labelledby="status-title" onClick={e=>e.stopPropagation()}><header><h2 id="status-title">Change lead status?</h2><button onClick={()=>{setPendingStatus(null);setStatusTarget(null)}} aria-label="Close"><FiX/></button></header><div className="action-modal-body"><div className="status-transition"><span>{statusLead.status}</span><FiChevronRight/><strong>{pendingStatus}</strong></div><p>This updates {statusLead.name} and adds the change to its activity history.</p>{['Won','Lost'].includes(pendingStatus)&&<label>{pendingStatus==='Won'?'Outcome':'Reason'}<textarea placeholder={pendingStatus==='Won'?'Add the result or deal value…':'Why was this lead lost?'} value={statusReason} onChange={e=>setStatusReason(e.target.value)}/></label>}</div><footer><button onClick={()=>{setPendingStatus(null);setStatusTarget(null)}}>Cancel</button><button className="primary" onClick={confirmStatus}>Confirm change</button></footer></div></div>}
  </>;
}

function Finder({notify,leads,setLeads,setPage,finderView,setFinderView}:{notify:(s:string)=>void;leads:Lead[];setLeads:React.Dispatch<React.SetStateAction<Lead[]>>;setPage:(page:Page)=>void;finderView:string;setFinderView:(view:string)=>void}) {
  const [phase,setPhase]=useState<'setup'|'searching'|'results'|'import'|'complete'>('setup'); const [progress,setProgress]=useState(0); const [criteria,setCriteria]=useState({industry:'Dental clinics',location:'Cebu City',count:'100'}); const [requirements,setRequirements]=useState(['Phone','Website']); const [selected,setSelected]=useState<string[]>([]); const [preview,setPreview]=useState<(typeof foundLeads)[number]|null>(null); const [resultQuery,setResultQuery]=useState(''); const [resultFilter,setResultFilter]=useState('All results'); const [resultSort,setResultSort]=useState('Highest score'); const [importForm,setImportForm]=useState({owner:'Shaun',priority:'Medium',status:'New',date:''}); const [importedNames,setImportedNames]=useState<string[]>([]); const [formError,setFormError]=useState(''); const [searches,setSearches]=useState<FinderSearch[]>(initialFinderSearches);
  const steps=['Searching verified business sources','Checking contact information','Removing existing leads','Scoring marketing opportunity']; const existingNames=useMemo(()=>new Set(leads.map(l=>l.name.toLowerCase())),[leads]);
  useEffect(()=>{if(phase!=='searching')return;const timer=setInterval(()=>setProgress(value=>{const next=value+1;if(next>=steps.length){clearInterval(timer);setSearches(items=>[{id:Date.now(),name:`${criteria.location} ${criteria.industry}`.trim(),industry:criteria.industry,location:criteria.location,count:criteria.count,found:foundLeads.length,added:0,lastRun:'Just now',status:'Complete',saved:false},...items]);setPhase('results');return steps.length}return next}),650);return()=>clearInterval(timer)},[phase,steps.length,criteria]);
  const results=useMemo(()=>foundLeads.filter(lead=>{const existing=existingNames.has(lead.name.toLowerCase());const queryMatch=(lead.name+lead.location+lead.need).toLowerCase().includes(resultQuery.toLowerCase());const filterMatch=resultFilter==='All results'||(resultFilter==='Qualified'&&lead.score>=80&&!existing)||(resultFilter==='High fit'&&lead.score>=90&&!existing)||(resultFilter==='Existing leads'&&existing);return queryMatch&&filterMatch}).sort((a,b)=>resultSort==='Highest score'?b.score-a.score:resultSort==='Lowest score'?a.score-b.score:a.name.localeCompare(b.name)),[existingNames,resultFilter,resultQuery,resultSort]);
  const availableResults=results.filter(lead=>!existingNames.has(lead.name.toLowerCase()));
  useEffect(()=>{if(finderView!=='New search'){setPhase('setup');setPreview(null);setProgress(0)}},[finderView]);
  const run=()=>{if(!criteria.industry.trim()||!criteria.location.trim()){setFormError('Industry and location are required.');return}setFormError('');setProgress(0);setSelected([]);setPhase('searching')};
  const toggleRequirement=(item:string)=>setRequirements(value=>value.includes(item)?value.filter(entry=>entry!==item):[...value,item]);
  const toggleLead=(name:string)=>setSelected(value=>value.includes(name)?value.filter(entry=>entry!==name):[...value,name]);
  const confirmImport=()=>{const chosen=foundLeads.filter(lead=>selected.includes(lead.name)&&!existingNames.has(lead.name.toLowerCase()));const newLeads:Lead[]=chosen.map(lead=>({name:lead.name,industry:lead.industry,city:lead.location,status:importForm.status,score:lead.score,owner:importForm.owner,last:'Just now',next:`Initial call · ${importForm.date||'Not scheduled'}`,phone:lead.phone,email:lead.email,contact:lead.contact,priority:importForm.priority,opportunity:lead.need}));setLeads(value=>[...newLeads,...value]);setSearches(value=>value.map((search,index)=>index===0&&search.industry===criteria.industry&&search.location===criteria.location?{...search,added:newLeads.length}:search));setImportedNames(newLeads.map(lead=>lead.name));setPhase('complete');notify(`${newLeads.length} leads added`)};
  const undoImport=()=>{setLeads(value=>value.filter(lead=>!importedNames.includes(lead.name)));setSelected([]);setImportedNames([]);setPhase('results');notify('Import undone')};
  const resetSearch=()=>{setPhase('setup');setProgress(0);setSelected([]);setPreview(null);setResultQuery('');setResultFilter('All results')};
  const openSearch=(search:FinderSearch,runNow=false)=>{setCriteria({industry:search.industry,location:search.location,count:search.count});setFinderView('New search');setSelected([]);setResultQuery('');setResultFilter('All results');setProgress(0);setPhase(runNow?'searching':'results')};
  const saveCurrentSearch=()=>{const duplicate=searches.some(search=>search.saved&&search.industry===criteria.industry&&search.location===criteria.location);if(duplicate){notify('Search is already saved');return}setSearches(value=>[{id:Date.now(),name:`${criteria.location} ${criteria.industry}`.trim(),industry:criteria.industry,location:criteria.location,count:criteria.count,found:0,added:0,lastRun:'Not run',status:'Saved',saved:true},...value]);notify('Search saved')};
  const deleteSearch=(id:number)=>{setSearches(value=>value.filter(search=>search.id!==id));notify('Search removed')};
  const recentTable=(rows:FinderSearch[],compact=false)=><div className={`finder-history ${compact?'compact':''}`}><div className="finder-history-head"><span>Search</span><span>Location</span><span>Found</span><span>Added</span><span>Last run</span><span>Status</span><span/></div>{rows.map(search=><div className="finder-history-row" key={search.id}><span><strong>{search.name}</strong><small>{search.industry} · {search.count} leads</small></span><span>{search.location}</span><span>{search.found||'—'}</span><span>{search.added||'—'}</span><span>{search.lastRun}</span><span><i className={`history-status ${search.status.toLowerCase()}`}/>{search.status}</span><span className="history-actions"><button onClick={()=>openSearch(search,search.status==='Saved')}>{search.status==='Complete'?'View results':'Run search'}</button><button aria-label={`Delete ${search.name}`} onClick={()=>deleteSearch(search.id)}><FiX/></button></span></div>)}</div>;
  if(finderView==='Campaigns')return <><Heading title="Campaigns" action={<button className="primary" onClick={()=>setFinderView('New search')}><FiPlus/> New search</button>}/><div className="campaign-summary"><div><strong>{searches.filter(search=>search.status==='Complete').length}</strong><span>Completed searches</span></div><div><strong>{searches.reduce((total,search)=>total+search.found,0)}</strong><span>Businesses found</span></div><div><strong>{searches.reduce((total,search)=>total+search.added,0)}</strong><span>Leads added</span></div></div>{recentTable(searches.filter(search=>search.status!=='Saved'))}</>;
  if(finderView==='Saved searches')return <><Heading title="Saved searches" action={<button className="primary" onClick={()=>setFinderView('New search')}><FiPlus/> New search</button>}/><div className="saved-search-intro"><strong>{searches.filter(search=>search.saved).length} saved searches</strong><span>Reuse proven criteria without rebuilding the search.</span></div>{recentTable(searches.filter(search=>search.saved))}</>;
  return <><Heading title="Lead Finder" action={phase==='results'?<button className="secondary finder-new-search" onClick={resetSearch}>New search</button>:undefined}/>
    {(phase==='setup'||phase==='searching')&&<><form className="finder-search-panel" onSubmit={e=>{e.preventDefault();run()}}><label>Industry<input value={criteria.industry} onChange={e=>setCriteria({...criteria,industry:e.target.value})}/></label><label>Location<input value={criteria.location} onChange={e=>setCriteria({...criteria,location:e.target.value})}/></label><label>Lead count<CustomSelect value={criteria.count} options={['25','50','100','250']} onChange={value=>setCriteria({...criteria,count:value})}/></label><div className="finder-requirements"><span>Required information</span><div>{['Phone','Website','Email','Social'].map(item=><button type="button" className={requirements.includes(item)?'active':''} onClick={()=>toggleRequirement(item)} key={item}>{requirements.includes(item)&&<FiCheck/>}{item}</button>)}</div></div><div className="finder-search-actions"><button type="button" onClick={saveCurrentSearch}>Save search</button><button className="primary" disabled={phase==='searching'}>{phase==='searching'?'Searching…':'Find leads'}</button></div></form>{formError&&<p className="finder-error">{formError}</p>}{phase==='searching'?<section className="finder-progress"><div><strong>Searching {criteria.location}</strong><span>{Math.round(progress/steps.length*100)}%</span></div><div className="progress-track"><i style={{width:`${progress/steps.length*100}%`}}/></div><div className="progress-steps">{steps.map((step,index)=><span className={progress>index?'done':progress===index?'active':''} key={step}>{progress>index?<FiCheck/>:<i/>}{step}</span>)}</div><button onClick={()=>{setPhase('setup');setProgress(0)}}>Cancel search</button></section>:<section className="recent-searches"><div className="finder-section-head"><h2>Recent searches</h2><button onClick={()=>setFinderView('Campaigns')}>View campaigns →</button></div>{recentTable(searches.filter(search=>search.status==='Complete').slice(0,3),true)}</section>}</>}
    {phase==='results'&&<div className="finder-results"><div className="finder-metrics"><div><strong>{foundLeads.length}</strong><span>Businesses found</span></div><div><strong>{foundLeads.filter(lead=>lead.score>=80&&!existingNames.has(lead.name.toLowerCase())).length}</strong><span>Qualified</span></div><div><strong>{foundLeads.filter(lead=>existingNames.has(lead.name.toLowerCase())).length}</strong><span>Already in Leads</span></div><button className="primary" disabled={!selected.length} onClick={()=>setPhase('import')}>Add selected ({selected.length})</button></div><div className="finder-review-bar"><div className="lead-search"><FiSearch/><input placeholder="Search results…" value={resultQuery} onChange={e=>setResultQuery(e.target.value)}/></div><CustomSelect value={resultFilter} options={['All results','Qualified','High fit','Existing leads']} onChange={setResultFilter}/><CustomSelect value={resultSort} options={['Highest score','Lowest score','Business name']} onChange={setResultSort}/><span>{results.length} results</span></div><div className="finder-result-table table"><div className="finder-result-head"><span><input type="checkbox" aria-label="Select all results" checked={availableResults.length>0&&availableResults.every(lead=>selected.includes(lead.name))} onChange={()=>setSelected(availableResults.every(lead=>selected.includes(lead.name))?selected.filter(name=>!availableResults.some(lead=>lead.name===name)):[...new Set([...selected,...availableResults.map(lead=>lead.name)])])}/></span><span>Business</span><span>Location</span><span>Opportunity</span><span>Source</span><span>Fit score</span><span/></div>{results.map(lead=>{const existing=existingNames.has(lead.name.toLowerCase());return <div className={`finder-result-row ${existing?'existing':''}`} role="button" tabIndex={0} onClick={()=>setPreview(lead)} onKeyDown={e=>e.key==='Enter'&&setPreview(lead)} key={lead.name}><span><input type="checkbox" aria-label={`Select ${lead.name}`} disabled={existing} checked={selected.includes(lead.name)} onClick={e=>e.stopPropagation()} onChange={()=>toggleLead(lead.name)}/></span><span><strong>{lead.name}</strong><small>{lead.website}</small></span><span>{lead.location}</span><span><i className={`fit-dot fit-${lead.score>=90?'high':lead.score>=80?'medium':'low'}`}/>{lead.need}</span><span>{lead.source}</span><span className="finder-score"><strong>{lead.score}</strong><small>{lead.score>=90?'High fit':lead.score>=80?'Qualified':'Review'}</small></span><span>{existing?<em>Existing</em>:<FiChevronRight/>}</span></div>})}{results.length===0&&<div className="finder-empty"><strong>No matching businesses</strong><button onClick={()=>{setResultQuery('');setResultFilter('All results')}}>Clear filters</button></div>}</div></div>}
    {phase==='complete'&&<section className="import-complete"><span><FiCheck/></span><h2>{importedNames.length} leads added</h2><p>They are assigned to {importForm.owner} and ready for the first follow-up.</p><div><button onClick={undoImport}>Undo</button><button className="primary" onClick={()=>setPage('Leads')}>View in Leads</button></div></section>}
    {preview&&<div className="drawer-backdrop" onClick={()=>setPreview(null)}><aside className="lead-drawer finder-preview" onClick={e=>e.stopPropagation()}><header className="drawer-header"><div><h2>{preview.name}</h2><p>{preview.industry} · {preview.location}</p></div><button onClick={()=>setPreview(null)} aria-label="Close"><FiX/></button></header><div className="finder-preview-score"><div><span>Fit score</span><strong>{preview.score}</strong></div><div><span>Opportunity</span><strong>{preview.need}</strong></div></div><section className="drawer-section contact-section"><h3>Business details</h3><div><p><span>Contact</span>{preview.contact}</p><p><span>Phone</span>{preview.phone}</p><p><span>Email</span>{preview.email}</p><p><span>Source</span>{preview.source}</p></div></section><section className="drawer-section finder-assessment"><h3>Scout assessment</h3><p>{preview.website}. The strongest opportunity is {preview.need.toLowerCase()}.</p></section><div className="close-actions">{existingNames.has(preview.name.toLowerCase())?<button onClick={()=>{setPreview(null);setPage('Leads')}}>View existing lead</button>:<button className="primary" onClick={()=>{setSelected(value=>value.includes(preview.name)?value:[...value,preview.name]);setPreview(null);setPhase('import')}}>Add to Leads</button>}</div></aside></div>}
    {phase==='import'&&<div className="action-modal-backdrop" onClick={()=>setPhase('results')}><div className="action-modal finder-import-modal" role="dialog" aria-modal="true" aria-labelledby="import-title" onClick={e=>e.stopPropagation()}><header><div><h2 id="import-title">Add {selected.length} leads</h2><p>Set ownership and the first workflow step.</p></div><button onClick={()=>setPhase('results')} aria-label="Close"><FiX/></button></header><div className="action-modal-body"><div className="form-split"><label>Owner<CustomSelect value={importForm.owner} options={['Shaun','Mika','Paolo']} onChange={value=>setImportForm({...importForm,owner:value})}/></label><label>Priority<CustomSelect value={importForm.priority} options={['Low','Medium','High']} onChange={value=>setImportForm({...importForm,priority:value})}/></label></div><div className="form-split"><label>Initial status<CustomSelect value={importForm.status} options={['New','Contacted','Interested']} onChange={value=>setImportForm({...importForm,status:value})}/></label><label>First follow-up<input type="date" value={importForm.date} onChange={e=>setImportForm({...importForm,date:e.target.value})}/></label></div><div className="import-review"><strong>{selected.length} ready to add</strong><span>Duplicates are automatically excluded.</span></div></div><footer><button onClick={()=>setPhase('results')}>Cancel</button><button className="primary" onClick={confirmImport}>Add to Leads</button></footer></div></div>}
  </>;
}

function Pipeline({leads,setLeads}:{leads:Lead[];setLeads:React.Dispatch<React.SetStateAction<Lead[]>>}) {
  const stages=['New','Contacted','Interested','Follow-up','Proposal','Negotiation','Won'];
  const advance=(stage:string,name:string)=>{const next=stages[stages.indexOf(stage)+1];if(next)setLeads(v=>v.map(l=>l.name===name?{...l,status:next}:l))};
  return <><Heading title="Pipeline" action={<button className="primary"><FiPlus/> Add opportunity</button>}/><div className="kanban">{stages.map((stage,idx)=>{const stageLeads=leads.filter(l=>l.status===stage);return <section key={stage}><header><span>{stage}</span><b>{stageLeads.length}</b></header>{stageLeads.map(l=><article key={l.name}><small>Score {l.score}</small><strong>{l.name}</strong><span>{l.next}</span>{idx<stages.length-1&&<button onClick={()=>advance(stage,l.name)} aria-label={`Move ${l.name} forward`}><FiChevronRight/></button>}</article>)}</section>})}</div></>;
}

function Tasks({leads,setLeads}:{leads:Lead[];setLeads:React.Dispatch<React.SetStateAction<Lead[]>>}) {
  const [done,setDone]=useState<string[]>([]);
  const rows=leads.filter(l=>!['Won','Lost'].includes(l.status)).map(l=>[l.next.split(' · ')[1]||'—',l.name,l.next.split(' · ')[0],l.priority]);
  const complete=(name:string)=>{setDone(v=>[...v,name]);setLeads(v=>v.map(l=>l.name===name?{...l,next:'Completed · Today'}:l))};
  return <><Heading title="Tasks" action={<button className="primary"><FiPlus/> Create task</button>}/><div className="task-controls"><button className="active">Today <span>{rows.length}</span></button><button>Upcoming</button><button>Completed</button><select><option>Assigned to me</option><option>Everyone</option></select></div><div className="tasks-full">{rows.map(t=><div className={done.includes(t[1])?'done':''} key={t[1]}><time>{t[0]}</time><button className="check" onClick={()=>complete(t[1])}>{done.includes(t[1])?'✓':''}</button><span><strong>{t[1]}</strong><small>{t[2]}</small></span><em className={`priority ${t[3].toLowerCase()}`}>{t[3]}</em><button><FiMoreHorizontal/></button></div>)}</div></>;
}

function Activities({activities}:{activities:ActivityEntry[]}) {
  return <><Heading title="Activities"/><div className="activity-filters"><button className="active">All activity</button><button>Calls</button><button>Notes</button><button>Proposals</button><button>Status changes</button><span/><select><option>Entire team</option><option>Shaun</option></select></div><div className="timeline">{activities.map(a=><article key={a.id}><div><time>{a.time}</time><i/></div><span>{a.type}</span><p><strong>{a.lead}</strong><small>{a.detail}</small></p><em>{a.owner}</em></article>)}</div></>;
}

export default function Home() {
  const [page,setPage]=useState<Page>('Overview'); const [command,setCommand]=useState(false); const [toast,setToast]=useState(''); const [leads,setLeads]=useState<Lead[]>(baseLeads); const [activities,setActivities]=useState<ActivityEntry[]>(initialActivities); const [leadView,setLeadView]=useState('All leads'); const [finderView,setFinderView]=useState('New search');
  useEffect(()=>{const h=(e:KeyboardEvent)=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();setCommand(v=>!v)}if(e.key==='Escape')setCommand(false)};window.addEventListener('keydown',h);return()=>window.removeEventListener('keydown',h)},[]);
  const notify=(s:string)=>{setToast(s);setTimeout(()=>setToast(''),2600)};
  return <Shell page={page} setPage={setPage} openCommand={()=>setCommand(true)}><div className="workspace"><UtilityRail page={page} setPage={setPage}/><ContextSidebar page={page} setPage={setPage} leadView={leadView} setLeadView={setLeadView} finderView={finderView} setFinderView={setFinderView}/><section className="content">{page==='Overview'&&<Overview setPage={setPage} leads={leads}/>} {page==='Leads'&&<Leads leads={leads} setLeads={setLeads} activities={activities} setActivities={setActivities} leadView={leadView} notify={notify}/>} {page==='Finder'&&<Finder notify={notify} leads={leads} setLeads={setLeads} setPage={setPage} finderView={finderView} setFinderView={setFinderView}/>} {page==='Pipeline'&&<Pipeline leads={leads} setLeads={setLeads}/>} {page==='Tasks'&&<Tasks leads={leads} setLeads={setLeads}/>} {page==='Activities'&&<Activities activities={activities}/>}</section></div>
    {command&&<div className="command-backdrop" onClick={()=>setCommand(false)}><div className="command" onClick={e=>e.stopPropagation()}><input autoFocus placeholder="Search anything…"/><p>Navigate</p>{(['Overview','Leads','Finder','Pipeline','Tasks','Activities'] as Page[]).map(p=><button key={p} onClick={()=>{setPage(p);setCommand(false)}}><span>{p}</span><kbd>↵</kbd></button>)}<p>Quick actions</p><button onClick={()=>{setPage('Finder');setCommand(false)}}><span>Find businesses</span><small>Start a new campaign</small></button></div></div>}{toast&&<div className="toast">✓ {toast}</div>}
  </Shell>;
}
